import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.doxMM-x8.js";const u=JSON.parse('{"title":"Maintain Project Documentation","description":"","frontmatter":{"docLocale":"en","counterpart":"/guides/documentation","contentType":"guide","prev":false,"next":{"text":"Publish documentation","link":"/en/getting-started/publish-docs"}},"headers":[],"relativePath":"en/guides/documentation.md","filePath":"en/guides/documentation.md"}'),o={name:"en/guides/documentation.md"};function i(s,e,d,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[n(`<h1 id="maintain-project-documentation" tabindex="-1">Maintain Project Documentation <a class="header-anchor" href="#maintain-project-documentation" aria-label="Permalink to &quot;Maintain Project Documentation&quot;">​</a></h1><p>Goal: help readers run Lab Word tasks and find current reference information. The writing pattern follows <a href="https://github.com/CaiZongyuan/axum-saas-template/tree/83f1f71bd166af8b604dd50124abc85242b82177/docs" target="_blank" rel="noreferrer">axum-saas-template</a>, as inspected on 2026-10-01. Topics and facts come from the current Lab Word source.</p><h2 id="choose-a-reader-task" tabindex="-1">Choose A Reader Task <a class="header-anchor" href="#choose-a-reader-task" aria-label="Permalink to &quot;Choose A Reader Task&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Content order</th><th>Completion</th></tr></thead><tbody><tr><td>Tutorial</td><td>Goal, prior code, complete change, run, result, failure check, next chapter</td><td>Continue the same Lab code</td></tr><tr><td>Guide</td><td>Goal, prerequisites, source/public interface, complete minimal operation, verification, recovery</td><td>Complete the task independently</td></tr><tr><td>Concept</td><td>Definition, real relationship diagram, minimal example, tradeoffs, limits, practical guide</td><td>Understand when it applies and where it fails</td></tr><tr><td>Reference</td><td>Source, classification, parameters, returns, errors, limits, usage</td><td>Find the current contract</td></tr><tr><td>Overview</td><td>Product scope, current stage, task entries, first result</td><td>Know where to start</td></tr></tbody></table><p>The learning path covers equipment inspection, GLB import and Lab development. Link to platform topics when a Lab task needs them. Product documentation excludes historical template tickets, generic SaaS courses and template promotion.</p><h2 id="write-a-verifiable-path" tabindex="-1">Write A Verifiable Path <a class="header-anchor" href="#write-a-verifiable-path" aria-label="Permalink to &quot;Write A Verifiable Path&quot;">​</a></h2><p>Inspect the public interface and current source. Write a complete path: source location, operation, command, expected result, then one failure and recovery. State the working directory, dependencies and placeholder values. Explain whether the operation writes persistent data. Explain the reasons after the reader gets the first result.</p><p>State whether a feature is implemented, an isolated preview or planned. For screenshots, record the source version and identify simulated accounts or data. The footer SHA identifies the source used to build the site. It does not prove that the documented commands were tested.</p><h2 id="simplified-technical-language" tabindex="-1">Simplified Technical Language: ASD-STE100-inspired <a class="header-anchor" href="#simplified-technical-language" aria-label="Permalink to &quot;Simplified Technical Language: ASD-STE100-inspired {#simplified-technical-language}&quot;">​</a></h2><p>Public documentation aims to be <strong>80% of the way to ASD-STE100</strong>. Use the principles of <a href="https://www.asd-ste100.org/" target="_blank" rel="noreferrer">ASD-STE100 Simplified Technical English</a> to make actions, conditions and results easy to understand. The percentage describes our writing approach. It is not a measured compliance score. Lab Word does not claim full compliance with the STE writing rules or controlled dictionary.</p><table tabindex="0"><thead><tr><th>Rule</th><th>How to apply it in Lab Word</th></tr></thead><tbody><tr><td>Use short sentences with one main idea</td><td>Aim for up to 20 words in English instructions and 25 words in descriptions. Split longer sentences first. In Chinese, split by meaning rather than English word counts.</td></tr><tr><td>Use active voice and name the actor</td><td>Start instructions with a verb, such as <code>Open</code>, <code>Run</code> or <code>Select</code>. For system behavior, name the API, Worker or browser that acts.</td></tr><tr><td>Give one action per step</td><td>Use numbered steps. Put the expected result immediately after the action. Put dependencies, permissions, conditions and warnings before the related action.</td></tr><tr><td>Use common words with stable meanings</td><td>Prefer <code>use</code>, <code>start</code>, <code>stop</code> and <code>check</code>. Use one term for each concept. Follow <a href="https://github.com/CaiZongyuan/labworld/blob/2fef28c35afea44ae2018f0e4b6a3a18a96a2bf7/CONTEXT.md" target="_blank" rel="noreferrer">CONTEXT</a> for domain terms.</td></tr><tr><td>Keep exact technical names</td><td>Keep necessary terms, such as GLB and Entity, and explain them on first use. Preserve commands, paths, API fields, error codes and interface labels.</td></tr><tr><td>Make conditions and failures clear</td><td>State the trigger, result and recovery action. Preserve the distinctions between <code>must</code>, <code>should</code> and <code>can</code>. Preserve negation, units, numeric limits and permission boundaries.</td></tr></tbody></table><p>Keep each paragraph on one topic. Separate actions from explanations. Both languages must keep the same prerequisites, steps, results and failure boundaries. Use natural sentences in each language.</p><p>For example, replace &quot;After adding SQL, migrate and restart development so the embedded migration set is refreshed.&quot; with:</p><ol><li>After you add SQL migrations, run <code>just migrate</code>.</li><li>Restart development.</li></ol><p>The restart updates the migration set in the binary.</p><p>Before delivery, review each changed passage against the table. Compare it with the source and the other language version. Word counts guide editing; they do not replace a review of meaning. <code>docs:check</code> checks documentation structure and source relationships. It does not validate STE compliance.</p><h2 id="register-and-validate" tabindex="-1">Register And Validate <a class="header-anchor" href="#register-and-validate" aria-label="Permalink to &quot;Register And Validate&quot;">​</a></h2><ol><li>Create an English <code>.en.md</code> file next to the Chinese source.</li><li>Register the page in <a href="https://github.com/CaiZongyuan/labworld/blob/2fef28c35afea44ae2018f0e4b6a3a18a96a2bf7/docs/site.json" target="_blank" rel="noreferrer">site.json</a>.</li><li>For a chapter sequence, set <code>previous</code> and <code>next</code> to the related chapter ids.</li></ol><p>The registration needs one stable id, both titles and sources, published routes, a group and a page type. Pages without a chapter relationship have no automatic previous or next page.</p><p>Repository Markdown is the source of page content. Current Node Zod/OpenAPI and frozen legacy OpenAPI provide API facts. The Node parser and frozen Settings provide configuration facts. Use <code>&lt;&lt;&lt;</code> to include checked, complete source code. Scripts generate <code>apps/docs/.generated</code> and the build output. Put site images in <code>apps/docs/public/</code>.</p><p>Run these checks from the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> e2e-docs</span></span></code></pre></div><p>The first two commands check sources, language pairs, generated references and links in the built site. Browser tests check language, theme, search and the deployment base. Use the <a href="https://github.com/CaiZongyuan/labworld/blob/2fef28c35afea44ae2018f0e4b6a3a18a96a2bf7/docs/testing/strategy.md" target="_blank" rel="noreferrer">testing strategy</a> to check business HTTP behavior, components and actual 3D rendering separately.</p><p>Lab Word has not published the learning paths from the original template. The cleanup removed unrelated pages and kept routes for adopted chapters. When you reorganize published Lab pages, preserve their existing links. Check that every navigation entry has a destination.</p><h2 id="maintainer-entries" tabindex="-1">Maintainer Entries <a class="header-anchor" href="#maintainer-entries" aria-label="Permalink to &quot;Maintainer Entries&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/labworld/blob/2fef28c35afea44ae2018f0e4b6a3a18a96a2bf7/CONTEXT.md" target="_blank" rel="noreferrer">CONTEXT</a> defines the vocabulary. <a href="https://github.com/CaiZongyuan/labworld/blob/2fef28c35afea44ae2018f0e4b6a3a18a96a2bf7/docs/adr/0005-lab-digital-twin-on-saas-foundation.md" target="_blank" rel="noreferrer">ADR 0005</a> records product boundaries. The <a href="https://github.com/CaiZongyuan/labworld/blob/2fef28c35afea44ae2018f0e4b6a3a18a96a2bf7/docs/agents/development-flow.md" target="_blank" rel="noreferrer">development flow</a> and <a href="https://github.com/CaiZongyuan/labworld/blob/2fef28c35afea44ae2018f0e4b6a3a18a96a2bf7/docs/agents/documentation.md" target="_blank" rel="noreferrer">author rules</a> define delivery. The original <a href="https://github.com/CaiZongyuan/labworld/blob/2fef28c35afea44ae2018f0e4b6a3a18a96a2bf7/docs/document-guild.md" target="_blank" rel="noreferrer">documentation philosophy</a> remains a writing reference.</p><p>After validation, follow the <a href="./../getting-started/publish-docs">publishing guide</a>.</p><hr><p>Source version：<code>2fef28c35afe</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/2fef28c35afea44ae2018f0e4b6a3a18a96a2bf7/docs/guides/maintain-docs.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,29)])])}const f=t(o,[["render",i]]);export{u as __pageData,f as default};
